import json,sys
d=json.load(open(sys.argv[1]))
def find(o,k):
    if isinstance(o,dict):
        if k in o: return o[k]
        for v in o.values():
            r=find(v,k)
            if r is not None: return r
for k in ("from","subject","date","snippet"): print(k,":",find(d,k))
print((find(d,"body") or "")[:600])
EOF

